- Create an `AutoTagger` struct with a method to generate tag suggestions.
- Store the suggestions separately from confirmed tags in the `Entry` model.

```swift
// src/services/nlp/AutoTagger.swift

import Foundation
import NaturalLanguage

enum AutoTagger {
    static func suggestTags(from text: String) -> [String] {
        let tagger = NLTagger(tagSchemes: [.lexicalClass])
        tagger.string = text

        var tags: Set<String> = []

        tagger.enumerateTags(in: text.startIndex..<text.endIndex, unit: .word, scheme: .lexicalClass) { tag, range in
            if let lexicalClass = tag?.rawValue {
                // Basic heuristic: add nouns and adjectives to the tag list
                if lexicalClass == "Noun" || lexicalClass == "Adjective" {
                    if let word = text[range] as? String {
                        tags.insert(word.lowercased())
                    }
                }
            }
            return true
        }

        // Limit to a reasonable number of suggestions
        return Array(tags).prefix(10)
    }
}
```

### Task 2: Live backlink resolver

**Objective:** Resolve live backlinks for an entry by scanning current mention references at view time.

#### Implementation:
- Implement the `BacklinkQuery` enum with methods to resolve backlinks and check if a mention is broken.

```swift
// src/services/backlinks/BacklinkQuery.swift

import CoreData

enum BacklinkQuery {
    static func backlinks(for entryID: UUID, in context: ModelContext) -> [Entry] {
        let fetchRequest = Entry.fetchRequest()
        fetchRequest.predicate = NSPredicate(format: "ANY outgoingMentions.targetEntryID == %@", entryID)

        do {
            return try context.fetch(fetchRequest)
        } catch {
            print("Error fetching backlinks: \(error)")
            return []
        }
    }

    static func isBroken(_ mention: Mention, in context: ModelContext) -> Bool {
        guard let targetEntry = mention.targetEntry else { return true }

        // Check if the target entry exists and hasn't been deleted
        do {
            let fetchRequest = Entry.fetchRequest()
            fetchRequest.predicate = NSPredicate(format: "id == %@", targetEntry.id)

            let results = try context.fetch(fetchRequest)
            return results.isEmpty || results.first?.isDemo ?? false
        } catch {
            print("Error checking broken backlink: \(error)")
            return true
        }
    }
}
```

### Task 3: Full-text search across transcripts, tags, and mood

**Objective:** Perform a full-text search across transcript text, tag names, and mood labels/values.

#### Implementation:
- Implement the `SearchRelevanceScorer` enum with methods to score and sort entries based on relevance.

```swift
// src/services/search/SearchRelevanceScorer.swift

import CoreData

enum SearchRelevanceScorer {
    static func score(entry: Entry, queryTokens: [String], now: Date) -> SearchScoreResult {
        var totalScore = 0.0
        var transcriptScore = 0.0
        var tagScore = 0.0
        var moodScore = 0.0

        // Transcript match
        let words = entry.cachedTranscriptText.lowercased().split(separator: " ")
        for token in queryTokens {
            if words.contains(token.lowercased()) {
                transcriptScore += 3.0
            }
        }

        // Tag match
        for tag in entry.tags {
            if queryTokens.contains(tag.name.lowercased()) {
                tagScore += 5.0
            }
        }

        // Mood match
        if let moodLabel = entry.moodLabel, queryTokens.contains(moodLabel.lowercased()) {
            moodScore += 4.0
        }

        totalScore = transcriptScore + tagScore + moodScore

        return SearchScoreResult(
            id: entry.id,
            entryID: entry.id,
            total: totalScore,
            transcriptScore: transcriptScore,
            tagScore: tagScore,
            moodScore: moodScore,
            recencyBonus: 0.0, // No recency bonus in this simple implementation
            matchReasons: []
        )
    }

    static func search(query: String, in entries: [Entry], now: Date) -> [SearchScoreResult] {
        let queryTokens = query.lowercased().split(separator: " ")

        return entries.map { entry in
            score(entry: entry, queryTokens: Array(queryTokens), now: now)
        }
        .filter { $0.total > 0.0 } // Exclude zero-score entries
        .sorted { $0.total > $1.total }
    }
}
```

